import { useState } from "react";

function SaveButton({ onSave }: { onSave: () => void }) {
  return (
    <button data-testid="missing-callback" onClick={onSave}>
      Missing callback prop wiring
    </button>
  );
}

export function App() {
  const [status, setStatus] = useState("idle");
  return (
    <div>
      <SaveButton onSave={() => setStatus("fixed")} />
      <span data-testid="status">{status}</span>
    </div>
  );
}
